package thaumcraft.taint;
import java.util.Random;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.RandomSource;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.phys.shapes.*;
public class TaintBlock extends Block{
 public enum Kind{FIBRE("taint_fibre"),CRUST("taint_crust"),SOIL("taint_soil"),ROCK("taint_rock"),GEYSER("taint_geyser"),LOG("taint_log"),FEATURE("taint_feature");public final String id;Kind(String id){this.id=id;}}
 public static final EnumProperty<Direction.Axis> AXIS=BlockStateProperties.AXIS;public static final EnumProperty<Direction> FACING=BlockStateProperties.FACING;public static final IntegerProperty GROWTH=IntegerProperty.create("growth",0,4);public static final BooleanProperty[] SIDES={BlockStateProperties.DOWN,BlockStateProperties.UP,BlockStateProperties.NORTH,BlockStateProperties.SOUTH,BlockStateProperties.WEST,BlockStateProperties.EAST};
 public final Kind kind;
 public TaintBlock(Kind k,Properties p){super(p);kind=k;}
 public static TaintBlock create(Kind k,Properties p){return switch(k){case FIBRE->new Fibre(p);case LOG->new Log(p);case FEATURE->new Feature(p);default->new TaintBlock(k,p);};}
 public void die(ServerLevel l,BlockPos p){var next=kind==Kind.SOIL?Blocks.DIRT.defaultBlockState():kind==Kind.ROCK?TaintContent.POROUS.get().defaultBlockState():kind==Kind.FIBRE?Blocks.AIR.defaultBlockState():TaintContent.GOO.get().defaultBlockState();TaintWorld.place(l,p,p,next,null);}
 protected void randomTick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){var presence=TaintWorld.presence(l,p);if(presence==TaintWorld.Presence.UNKNOWN)return;if(presence==TaintWorld.Presence.ABSENT){if(kind==Kind.FIBRE||kind==Kind.LOG||r.nextInt(10)==0)die(l,p);return;}if(kind==Kind.FIBRE||kind==Kind.LOG||kind==Kind.ROCK||kind==Kind.FEATURE)TaintWorld.spread(l,p,false);
  if(kind==Kind.CRUST&&l.hasChunkAt(p.below())&&l.getBlockState(p.below()).isAir()&&!TaintWorld.solidNeighbour(l,p,true)&&l.getGameRules().get(net.minecraft.world.level.gamerules.GameRules.MOB_GRIEFING)&&!net.minecraftforge.event.level.BlockEvent.FluidPlaceBlockEvent.BUS.post(new net.minecraftforge.event.level.BlockEvent.FluidPlaceBlockEvent(l,p,p,Blocks.AIR.defaultBlockState())))net.minecraft.world.entity.item.FallingBlockEntity.fall(l,p,s);
  if(kind==Kind.FEATURE&&l.getBlockState(p.below()).is(TaintContent.BLOCKS.get("taint_log").get())&&r.nextInt(100)==0)TaintWorld.place(l,p,p,TaintWorld.state("taint_geyser"),null);
  if(kind==Kind.GEYSER){if(r.nextFloat()<.2F&&l.hasNearbyAlivePlayer(p.getX()+.5,p.getY()+.5,p.getZ()+.5,32)&&l.getEntitiesOfClass(TaintedMob.class,new net.minecraft.world.phys.AABB(p).inflate(32),e->e.kind==TaintedMob.Kind.SWARM).isEmpty())TaintedMob.spawn(l,TaintedMob.Kind.SWARM,p.above());else {var a=thaumcraft.aura.AuraManager.get(l,p);if(a!=null&&a.flux()<2)thaumcraft.aura.AuraManager.addFlux(l,p,.25F);}}
 }
 public void stepOn(Level l,BlockPos p,BlockState s,Entity e){super.stepOn(l,p,s,e);if(l instanceof ServerLevel server&&e instanceof LivingEntity living&&!(e instanceof TaintedMob)&&!(e instanceof ThaumicSlime)&&!e.getType().builtInRegistryHolder().is(net.minecraft.tags.EntityTypeTags.UNDEAD)&&l.getRandom().nextInt(kind==Kind.FIBRE?750:250)==0)living.addEffect(new net.minecraft.world.effect.MobEffectInstance(TaintContent.DISEASE.getHolder().orElseThrow(),200));}
 public static final class Log extends TaintBlock{public Log(Properties p){super(Kind.LOG,p);registerDefaultState(stateDefinition.any().setValue(AXIS,Direction.Axis.Y));}protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(AXIS);}public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(AXIS,c.getClickedFace().getAxis());}}
 public static final class Feature extends TaintBlock{public Feature(Properties p){super(Kind.FEATURE,p);registerDefaultState(stateDefinition.any().setValue(FACING,Direction.UP));}protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FACING);}public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,c.getClickedFace());}protected VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return switch(s.getValue(FACING)){case UP->Block.box(2,0,2,14,10,14);case DOWN->Block.box(2,6,2,14,16,14);case NORTH->Block.box(2,2,6,14,14,16);case SOUTH->Block.box(2,2,0,14,14,10);case WEST->Block.box(6,2,2,16,14,14);case EAST->Block.box(0,2,2,10,14,14);};}protected BlockState updateShape(BlockState s,LevelReader l,ScheduledTickAccess ticks,BlockPos p,Direction d,BlockPos q,BlockState other,RandomSource r){var support=p.relative(s.getValue(FACING).getOpposite());if(l.hasChunkAt(support)&&!l.getBlockState(support).isFaceSturdy(l,support,s.getValue(FACING)))return Blocks.AIR.defaultBlockState();return s;}public BlockState playerWillDestroy(Level l,BlockPos p,BlockState s,net.minecraft.world.entity.player.Player user){if(l instanceof ServerLevel server){if(l.getRandom().nextFloat()<.333F)TaintedMob.spawn(server,TaintedMob.Kind.CRAWLER,p);else thaumcraft.aura.AuraManager.addFlux(server,p,1);}return super.playerWillDestroy(l,p,s,user);}}
 public static final class Fibre extends TaintBlock{public Fibre(Properties p){super(Kind.FIBRE,p);var s=stateDefinition.any().setValue(GROWTH,0);for(var side:SIDES)s=s.setValue(side,false);registerDefaultState(s);}protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(GROWTH);b.add(SIDES);}public BlockState connections(LevelReader l,BlockPos p,BlockState s){for(var d:Direction.values()){var q=p.relative(d);if(!l.hasChunkAt(q))continue;var other=l.getBlockState(q);s=s.setValue(SIDES[d.ordinal()],!(other.getBlock() instanceof Fibre)&&!other.is(TaintContent.BLOCKS.get("taint_feature").get())&&other.isFaceSturdy(l,q,d.getOpposite()));}int q=new Random(p.asLong()).nextInt(50),g=s.getValue(SIDES[0])?(q<4?1:q<6?2:q==6?3:0):0;if(s.getValue(SIDES[1])&&q>47)g=4;return s.setValue(GROWTH,g);}public BlockState getStateForPlacement(BlockPlaceContext c){return connections(c.getLevel(),c.getClickedPos(),defaultBlockState());}protected BlockState updateShape(BlockState s,LevelReader l,ScheduledTickAccess ticks,BlockPos p,Direction d,BlockPos q,BlockState other,RandomSource r){var next=connections(l,p,s);for(var side:SIDES)if(next.getValue(side))return next;return Blocks.AIR.defaultBlockState();}protected VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){var shape=Shapes.empty();for(var d:Direction.values())if(s.getValue(SIDES[d.ordinal()]))shape=Shapes.or(shape,switch(d){case DOWN->Block.box(0,0,0,16,1,16);case UP->Block.box(0,15,0,16,16,16);case NORTH->Block.box(0,0,0,16,16,1);case SOUTH->Block.box(0,0,15,16,16,16);case WEST->Block.box(0,0,0,1,16,16);case EAST->Block.box(15,0,0,16,16,16);});if(s.getValue(GROWTH)>0)shape=Shapes.or(shape,Block.box(3,0,3,13,s.getValue(GROWTH)==2?16:6,13));return shape;}}
}
